custom_css:
/* --- 独占欲 感谢代码楼里老师们的代码https://discord.com/channels/1291925535324110879/1380392618336194702
感谢尾老师，类名，输入框伪提示词来自尾老师，hy老师的去除思维链箭头，na老师的悬浮底栏和思维链文字自定义，楼层信息自定义，12老师的去思维链背景色。感谢NA老师的去阴影，感谢咩野老师的去除全局阴影.【神秘新卡专属美化】 --- */

/* --- 1. 字体导入 --- */
@import url('https://fonts.googleapis.com/css2?family=VT323&display=swap');
@import url('https://fonts.googleapis.com/css2?family=DotGothic16&display=swap');
@import url('https://fonts.googleapis.com/css2?family=Kiwi+Maru:wght@400;500&display=swap');
@import url('https://fonts.googleapis.com/css2?family=M+PLUS+Rounded+1c:wght@400;700&display=swap');
@import url("https://fontsapi.zeoseven.com/440/main/result.css");
@import url("https://fontsapi.zeoseven.com/45/main/result.css");
@import url("https://fontsapi.zeoseven.com/496/main/result.css");
@import url("https://fontsapi.zeoseven.com/495/main/result.css");

/* --- 2. 核心颜色与样式变量 --- */
:root {
    --theme-bg: #e2e8f0; /* 更暗一点的背景，衬托纯白卡片 */
    --panel-bg-color: rgba(255, 255, 255, 0.95);
    --panel-bg-hover: rgba(241, 245, 249, 1);
    --card-bg: rgba(255, 255, 255, 1);
    --input-bg: rgba(255, 255, 255, 0.95);
    --text-main: #0f172a;
    --text-subtle: #475569;
    --accent-blue: #0f2b5b; /* 极深的深蓝 */
    --accent-lightblue: #1e4a8f; /* 较亮的深蓝用于点缀 */
    --accent-white: #ffffff;
    --font-pixel: 'DotGothic16', 'VT323', monospace;
    --font-main: "Huiwen-Fangsong", 'M PLUS Rounded 1c', sans-serif;
    --font-quote: "PING FANG JIANG NAN TI", 'Kiwi Maru', serif;
    --font-code: "nzgrRuYinZouZhangKai", monospace;
    --font-title: "PING FANG ZHUI FENG", sans-serif;
}

/* --- 3. 全局样式与无阴影/无边框设定 --- */
* { box-shadow: none !important; }
body { 
    background-color: var(--theme-bg) !important; 
    background-image: linear-gradient(135deg, #e2e8f0 0%, #cbd5e1 100%);
    background-size: cover; background-position: center; background-attachment: fixed;
    color: var(--text-main); font-family: var(--font-main); font-weight: normal; 
}
/* 悬浮病娇文字动效 (颜色加深) */
body::after {
    content: '♡ ずっと一緒 ♡'; position: fixed; top: 15%; left: 5%; 
    font-family: var(--font-pixel); font-size: 24px; color: rgba(15, 43, 91, 0.25);
    pointer-events: none; z-index: 9999; animation: float-text-yandere 5s infinite alternate steps(10);
    writing-mode: vertical-rl;
}
body::before {
    content: '逃 が さ な い'; position: fixed; bottom: 15%; right: 5%;
    font-family: var(--font-title); font-size: 30px; color: rgba(15, 43, 91, 0.15);
    pointer-events: none; z-index: 9999; animation: float-text-yandere2 7s infinite alternate steps(8);
}
@keyframes float-text-yandere { 0% { transform: translateY(0) scale(1); letter-spacing: 5px; } 100% { transform: translateY(-20px) scale(1.05); letter-spacing: 15px; } }
@keyframes float-text-yandere2 { 0% { transform: translateY(0) translateX(0); opacity: 0.1; } 100% { transform: translateY(10px) translateX(-10px); opacity: 0.5; text-shadow: 2px 2px 5px var(--accent-lightblue); } }

#sheld, #character_view { background: transparent !important; margin: 0 auto !important; border: none !important; }
#chat { background: transparent !important; padding-bottom: 180px !important; }
h1, h2, h3, h4, .standoutHeader, .inline-drawer-header, .title_restorable { font-family: var(--font-title); color: var(--accent-blue); font-weight: bold; border: none !important; }

/* --- 4. 导航栏与贴图替换 --- */
#top-settings-holder { position:relative; background-color: var(--panel-bg-color); backdrop-filter: blur(8px); border: none !important; border-bottom: 3px dashed var(--accent-blue) !important; }
.drawer-icon.fa-fw::before { content: '' !important; font-size: 0 !important; }
.drawer-icon.fa-fw { width: 35px; height: 40px; background-size: contain; background-repeat: no-repeat; background-position: center; transition: all 0.2s steps(3); image-rendering: pixelated; }
.drawer-icon.fa-fw:hover { transform: translateY(-4px); filter: drop-shadow(0 4px 0px var(--accent-blue)); }

.drawer-icon.fa-sliders, #ai-config-button .drawer-icon, .drawer-icon.fa-font, #advanced-formatting-button .drawer-icon, .drawer-icon.fa-user, #user-settings-button .drawer-icon, .drawer-icon.fa-cubes, #extensions-settings-button .drawer-icon, .drawer-icon.fa-face-smile, #persona-management-button .drawer-icon { 
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260505/vE1R/761X1289/2026-05-05%2520135842.png/webp'); 
}
.drawer-icon.fa-plug, #sys-settings-button .drawer-icon, .drawer-icon.fa-book-atlas, #WI-SP-button .drawer-icon, .drawer-icon.fa-image, .drawer-icon.fa-panorama, .drawer-icon.fa-bars-progress, #table_database_settings_drawer .drawer-icon, .drawer-icon.fa-address-card, #character_popup_button .drawer-icon { 
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260505/XnQS/1130X1056/2026-05-05%2520135905.png/webp'); 
}

.drawer-content, dialog.popup .popup-body, #dialogue_popup {
    background-image: linear-gradient(rgba(255, 255, 255, 0.9), rgba(241, 245, 249, 0.95)), url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260505/jGgF/1200X675/a5dac4c4d4f05cab200ac871f67aef2d.jpg/webp') !important;
    background-size: cover; background-position: center; border: 3px solid var(--accent-blue) !important; border-radius: 12px;
}

/* --- 5. 底部悬浮栏 (加入呼吸动效与紧凑化) --- */
#send_textarea::placeholder { color: transparent !important; opacity: 0 !important; }
#form_sheld { position: absolute !important; bottom: 25px !important; left: 0; right: 0; display: flex; justify-content: center; z-index: 1000; pointer-events: none; overflow: visible !important; }
#send_form { 
    pointer-events: auto; width: 80% !important; max-width: 800px !important; margin: 0 auto !important; 
    background-color: var(--input-bg) !important; 
    padding: 8px 15px !important; /* 紧凑的内边距，防止占用过多空间 */
    backdrop-filter: blur(10px) !important; position: relative; 
    border: 4px solid var(--accent-blue) !important; 
    outline: 2px solid var(--accent-white) !important; border-radius: 16px !important;
    /* 呼吸动效 */
    animation: yandere-breathe 4s ease-in-out infinite;
}
@keyframes yandere-breathe {
    0%, 100% { transform: translateY(0); box-shadow: 0 0 0 transparent; }
    50% { transform: translateY(-6px); box-shadow: 0 10px 20px rgba(15, 43, 91, 0.15); }
}
#send_textarea { clip-path: none !important; border: none !important; background: transparent !important; color: var(--text-main) !important; }

#nonQRFormItems:has(#send_textarea:placeholder-shown)::before { 
    content: '私だけのもの…どこにも行かないで…♡'; 
    color: var(--accent-blue); position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); 
    font-family: var(--font-pixel); font-size: clamp(12px, 2vw, 18px); pointer-events: none; z-index: 10; 
    white-space: nowrap; letter-spacing: 2px; opacity: 0.8; animation: yandere-blink 2s infinite steps(2);
}
@keyframes yandere-blink { 0% { opacity: 0.4; } 100% { opacity: 1; } }

#options_button::before, #send_but::before, #send_form #extensionsMenuButton::before, #ai_retry_button::before, #auto_completion_button::before { display: none !important; }
#options_button, #send_but, #send_form #extensionsMenuButton, #ai_retry_button, #auto_completion_button { width: 32px; height: 32px; background-size: contain; background-repeat: no-repeat; background-position: center; transition: all 0.2s steps(2); font-size: 0; border: none !important; background-color: transparent; image-rendering: pixelated; margin: 0 2px; }
#options_button:hover, #send_but:hover, #send_form #extensionsMenuButton:hover, #ai_retry_button:hover, #auto_completion_button:hover { transform: translateY(-3px) scale(1.1); }

#options_button { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260505/X2z1/1272X1244/2026-05-05%2520135926.png/webp'); }
#send_form #extensionsMenuButton { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260505/X2z1/1272X1244/2026-05-05%2520135926.png/webp'); }
#send_but { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260505/gaQ2/1789X1659/2026-05-05%2520135805.png/webp'); }
#ai_retry_button { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260505/X2z1/1272X1244/2026-05-05%2520135926.png/webp'); filter: hue-rotate(180deg); }
#auto_completion_button { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260505/X2z1/1272X1244/2026-05-05%2520135926.png/webp'); filter: hue-rotate(90deg); }

/* --- 6. 消息框 PictoChat (3DS涂鸦聊天) 风格 --- */
.mes { 
    display: flex; flex-direction: column; 
    padding: 10px 10px 20px 40px !important; 
    margin: 50px auto 40px !important; 
    width: 85%; max-width: 800px; 

    background-color: #ffffff !important;
    /* 模拟笔记本线条，使用较淡的深蓝 */
    background-image: repeating-linear-gradient(transparent, transparent 39px, rgba(15, 43, 91, 0.1) 39px, rgba(15, 43, 91, 0.1) 40px) !important;
    background-position: 0 45px !important;

    border: 6px solid var(--accent-blue) !important; 
    border-radius: 12px !important;
    outline: 3px solid rgba(15, 43, 91, 0.15) !important; outline-offset: -9px !important;

    backdrop-filter: blur(5px) !important; overflow: visible !important; position: relative; 
}
.mes[is_user="false"] { border-color: var(--accent-blue) !important; }
.mes[is_user="true"] { border-color: var(--accent-lightblue) !important; background-color: #f8fafc !important; }

/* 侧边工具栏模拟 */
.mes::before {
    content: ''; position: absolute; top: 5px; bottom: 5px; left: 5px; width: 25px;
    background: #fff; border: 2px solid var(--accent-blue); border-radius: 6px; z-index: 5; pointer-events: none;
    background-image: linear-gradient(var(--accent-blue), var(--accent-blue)), linear-gradient(var(--accent-blue), var(--accent-blue)), linear-gradient(var(--accent-blue), var(--accent-blue));
    background-size: 15px 15px, 15px 15px, 15px 15px; background-position: center 10px, center 35px, center 60px; background-repeat: no-repeat;
}
.mes[is_user="true"]::before { border-color: var(--accent-lightblue); background-image: linear-gradient(var(--accent-lightblue), var(--accent-lightblue)), linear-gradient(var(--accent-lightblue), var(--accent-lightblue)), linear-gradient(var(--accent-lightblue), var(--accent-lightblue)); }

/* 顶部背景图 (高度扩大至160px) */
.mes .mesAvatarWrapper {
    display: flex; justify-content: flex-start; align-items: flex-end; padding: 0;
    width: calc(100% + 20px); 
    height: 160px !important; min-height: 160px !important; /* 调整高度 */
    margin-left: -10px; margin-top: -10px;
    background-size: cover; background-position: center; background-repeat: no-repeat;
    position: relative; z-index: 10 !important; overflow: visible !important;
    border-radius: 8px 8px 0 0; border-bottom: 3px solid var(--accent-blue);
}
.mes[is_user="false"] .mesAvatarWrapper { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260505/Jnnn/1024X512/4uhwg9Ps_converted.gif/webp'); }
.mes[is_user="true"] .mesAvatarWrapper { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260505/PdG9/1024X512/kns31pJX_converted.gif/webp'); border-bottom-color: var(--accent-lightblue); }

/* 角色名 (提升层级，确保不被背景图遮挡) */
.mes .mesAvatarWrapper > .ch_name { display: none !important; }
.mes .mes_block { position: relative; z-index: 20 !important; background-color: transparent !important; background-image: none !important; padding: 15px 10px 10px 10px !important; border: none !important; }
.mes .mes_block > .ch_name { 
    display: flex !important; position: absolute; top: -25px !important; left: 55px !important; 
    width: auto !important; height: auto !important;
    background: var(--card-bg) !important; border: 3px solid var(--accent-blue) !important; border-radius: 12px;
    padding: 2px 12px !important; 
    z-index: 1000 !important; /* 极高层级 */
}
.mes[is_user="true"] .mes_block > .ch_name { left: auto !important; right: 30px !important; border-color: var(--accent-lightblue) !important; }
.mes .ch_name > .flex-container { display: flex !important; align-items: center !important; gap: 8px !important; flex-wrap: nowrap !important; }
.mes .ch_name .name_text { font-family: var(--font-pixel) !important; font-size: 18px !important; color: var(--accent-blue) !important; font-weight: bold; background: transparent !important; padding: 0 !important; border: none !important; line-height: 1; }
.mes .ch_name .name_text::before { content: '♡ '; color: var(--accent-blue); }
.mes[is_user="true"] .ch_name .name_text { color: var(--accent-lightblue) !important; }
.mes[is_user="true"] .ch_name .name_text::before { color: var(--accent-lightblue); }

/* 头像 (提升层级) */
.mes .avatar {
    position: absolute; top: -40px; left: -20px; width: 65px; height: 65px; 
    background: #fff !important; padding: 2px !important; border: 3px solid var(--accent-blue) !important; border-radius: 12px !important;
    z-index: 1000 !important; /* 极高层级 */
    display: flex !important; align-items: center; justify-content: center;
}
.mes[is_user="true"] .avatar { right: -20px; left: auto; border-color: var(--accent-lightblue) !important; }
.mes .avatar img { width: 100% !important; height: 100% !important; object-fit: cover !important; border-radius: 8px !important; image-rendering: pixelated; }

/* 文本与排版 */
.mes .mes_text, .mes_reasoning { background: transparent !important; border: none !important; padding: 0 !important; margin: 0 !important; backdrop-filter: none !important; }

#chat .mes .mes_reasoning_header { background: transparent !important; border: none !important; padding: 0 !important; margin-bottom: 12px !important; display: inline-flex !important; align-items: center !important; }
.mes_reasoning_arrow { display: none !important; }
.mes_reasoning_header h4, .mes_reasoning_header_title { font-size: 0 !important; visibility: hidden; }
.mes_reasoning_header h4::before, .mes_reasoning_header_title::before { 
    content: "♡ あなたのことを考えてる… [執着解析中]..."; font-family: var(--font-pixel); font-size: 15px !important; color: var(--accent-blue); visibility: visible; letter-spacing: 1px; font-weight: bold;
}
.mes_reasoning { border-left: 4px dashed var(--accent-lightblue) !important; padding-left: 15px !important; margin-bottom: 20px !important; color: var(--text-subtle); font-family: var(--font-quote); font-size: 0.9em; }
.mes .mes_text { line-height: 1.8; color: var(--text-main); font-size: 17px; text-align: justify; }

.mes_text h1 { font-family: var(--font-title); color: var(--accent-blue); font-size: 1.8em; text-align: center; border-bottom: 2px dashed var(--accent-lightblue) !important; padding-bottom: 8px; margin: 20px 0; }
.mes_text h2 { font-family: var(--font-title); color: var(--accent-blue); font-size: 1.5em; border-left: 6px solid var(--accent-lightblue) !important; padding-left: 10px; margin: 15px 0; }
.mes_text em, .mes_text i { font-family: var(--font-quote); font-style: normal !important; color: var(--text-subtle); background: rgba(30, 74, 143, 0.1); padding: 2px 4px; border-radius: 4px; }
.mes_text strong, .mes_text b { font-family: var(--font-main); color: var(--accent-blue); font-weight: bold; }
.mes_text blockquote { background-color: rgba(255,255,255,0.8); border: 2px solid var(--accent-lightblue) !important; border-left: 6px solid var(--accent-blue) !important; padding: 12px; margin: 15px 0; font-family: var(--font-quote); border-radius: 8px; }
.mes_text code { font-family: var(--font-code) !important; background-color: #f1f5f9 !important; color: var(--accent-blue) !important; padding: 4px 8px; border: 1px dashed var(--accent-blue) !important; border-radius: 4px; }

/* 楼层自定义 */
.mes .mesIDDisplay { position: absolute; bottom: 5px !important; right: 15px !important; background: transparent !important; border: none !important; color: var(--accent-blue) !important; font-size: 13px !important; z-index: 100; font-family: var(--font-pixel); font-weight: bold; left: auto !important; transform: none !important; }
.mesIDDisplay::before { content: '監視記録 No.'; color: var(--text-subtle); }
.mesIDDisplay::after { content: ' ♡'; color: var(--text-subtle); }
.mes .mes_timer { display: none !important; }

/* --- UI及其他 --- */
.standoutHeader, .inline-drawer-header, .title_restorable, #extensions_settings2 > div, #extensions_settings > div, .openai_logit_bias_preset_form, details > summary, div[name*='Toggles'] h4 { background: var(--card-bg) !important; border: none !important; border-radius: 8px !important; padding: 10px 15px !important; margin-bottom: 8px !important; color: var(--accent-blue) !important; font-family: var(--font-pixel); font-weight: bold; }
input[type="text"], input[type="number"], input[type="search"], textarea, select, .text_pole { background-color: #f8fafc !important; border: 2px solid var(--accent-lightblue) !important; color: var(--text-main) !important; border-radius: 8px !important; padding: 6px !important; font-family: var(--font-pixel); }
input:focus, textarea:focus, select:focus { outline: none !important; border: 2px solid var(--accent-blue) !important; background-color: #fff !important; }
.menu_button { background-color: #fff !important; border: 2px solid var(--accent-blue) !important; color: var(--accent-blue) !important; transition: all 0.2s; border-radius: 8px !important; font-family: var(--font-pixel); font-weight: bold; }
.menu_button:hover, .menu_button.active, .menu_button.world_set, .menu_button.fav_on, #left-nav-panel .menu_button.selected { background-color: var(--accent-blue) !important; color: #fff !important; }

/* 消息编辑按钮 */
.mes .mes_buttons, .mes .mes_edit_buttons { flex-direction: row-reverse; gap: 6px; position: static !important; opacity: 0.3; transition: opacity 0.2s; pointer-events: auto !important; margin-top: 10px; }
.mes:hover .mes_buttons, .mes:hover .mes_edit_buttons { opacity: 1; }
.mes .mes_buttons .mes_button, .mes .mes_edit_buttons .mes_button { background-color: #fff !important; padding: 0 !important; cursor: pointer; height: 28px !important; width: 28px !important; border: 2px solid var(--accent-blue) !important; border-radius: 6px !important; display: inline-flex !important; align-items: center !important; justify-content: center !important; font-family: "Font Awesome 6 Free", "FontAwesome" !important; font-weight: 900 !important; font-size: 13px !important; color: var(--accent-blue) !important; -webkit-font-smoothing: antialiased !important; }
.mes .mes_buttons .mes_button:hover, .mes .mes_edit_buttons .mes_button:hover { background-color: var(--accent-blue) !important; transform: scale(1.1); }
/* 所有消息按钮 ::before 统一恢复 FontAwesome */
.mes .mes_buttons .mes_button::before, .mes .mes_edit_buttons .mes_button::before { display: inline-block !important; font-family: "Font Awesome 6 Free", "FontAwesome" !important; font-weight: 900 !important; font-size: 13px !important; color: var(--accent-blue) !important; -webkit-font-smoothing: antialiased !important; }
.mes .mes_buttons .mes_button:hover::before, .mes .mes_edit_buttons .mes_button:hover::before { color: #fff !important; }
/* mes_edit_buttons / mes_buttons 里 menu_button 恢复 FA 字体 */
.mes_edit_buttons .menu_button, .mes_buttons .menu_button { font-family: "Font Awesome 6 Free", "FontAwesome" !important; font-weight: 900 !important; font-size: 13px !important; -webkit-font-smoothing: antialiased !important; }
.mes_edit_buttons .menu_button::before, .mes_buttons .menu_button::before { font-family: "Font Awesome 6 Free", "FontAwesome" !important; font-weight: 900 !important; -webkit-font-smoothing: antialiased !important; }
/* form_create_bottom_buttons 及其他所有含 fa-solid 的 menu_button 恢复 FA 字体 */
.buttons_block .menu_button, .form_create_bottom_buttons .menu_button,
#form_create .menu_button, .fa-solid.menu_button, .fa-regular.menu_button { font-family: "Font Awesome 6 Free", "FontAwesome" !important; font-weight: 900 !important; font-size: 14px !important; -webkit-font-smoothing: antialiased !important; }
.buttons_block .menu_button::before, .form_create_bottom_buttons .menu_button::before,
#form_create .menu_button::before, .fa-solid.menu_button::before, .fa-regular.menu_button::before { display: inline-block !important; font-family: "Font Awesome 6 Free", "FontAwesome" !important; font-weight: 900 !important; font-size: 14px !important; -webkit-font-smoothing: antialiased !important; }

/* 手机适配 */
@media (max-width: 768px) {
    #send_form { width: 90% !important; }
    .mes { width: 95%; margin-bottom: 50px !important; padding-left: 35px !important; }
    .mes::before { width: 20px; left: 5px; }
    .mes .mes_block > .ch_name { left: 40px !important; top: -20px !important; }
    .mes .avatar { width: 50px; height: 50px; top: -25px; left: -15px; }
    .mes[is_user="true"] .avatar { right: -15px; left: auto; }
}

/* 1. 【核心】剥夺 mes_block 的定位基准，让内部元素直接参考最外层的 .mes 框！ */
.mes .mes_block {
    position: static !important; 
    padding-top: 15px !important; /* 给正文留出一点顶部空间 */
}

/* 2. 角色名现在直接相对于 .mes（整个大外框）定位，完全不受背景图高度干扰 */
.mes .mes_block > .ch_name { 
    display: flex !important; 
    position: absolute !important; 
    top: 120px !important; /* 相对于整个框的顶部边缘，精准跨出边框一点点 */
    left: 55px !important; 
    width: auto !important; height: auto !important;
    background: var(--card-bg) !important; 
    border: 3px solid var(--accent-blue) !important; 
    border-radius: 12px !important;
    padding: 2px 12px !important; 
    z-index: 99999 !important; /* 强制覆盖在最上层 */
}

/* 用户的名字靠右 */
.mes[is_user="true"] .mes_block > .ch_name { 
    left: auto !important; 
    right: 30px !important; 
    border-color: var(--accent-lightblue) !important; 
}

/* 名字文本内部样式 */
.mes .ch_name .flex-container { display: flex !important; align-items: center !important; gap: 8px !important; flex-wrap: nowrap !important; }
.mes .ch_name .name_text { font-family: var(--font-pixel) !important; font-size: 18px !important; color: var(--accent-blue) !important; font-weight: bold !important; background: transparent !important; padding: 0 !important; border: none !important; line-height: 1 !important; }
.mes .ch_name .name_text::before { content: '♡ '; color: var(--accent-blue); }
.mes[is_user="true"] .ch_name .name_text { color: var(--accent-lightblue) !important; }
.mes[is_user="true"] .ch_name .name_text::before { color: var(--accent-lightblue); }

/* 额外保险：避免冲突 */
.mes .mesAvatarWrapper > .ch_name { display: none !important; }

/* 4. 手机端适配同步修改 */
@media (max-width: 768px) {
    .mes .mes_block > .ch_name { 
        left: 40px !important; 
        top: -35px !important; 
        position: absolute !important; 
    }
}
